using static Microsoft.VisualStudio.TestTools.UnitTesting.Assert;

namespace SqlServerSimulator;

/// <summary>
/// The compile refusals a schema collection's text raises at <c>CREATE</c>
/// and <c>ALTER … ADD</c>, and the texts real accepts that a stricter
/// reading would refuse. Every expected number, state and message was probed
/// against SQL Server 2025 on 2026-10-16.
/// </summary>
[TestClass]
public sealed class XmlSchemaCompileTests
{
    private static string Text(string attributes, string body) =>
        $"<xs:schema xmlns:xs=\"http://www.w3.org/2001/XMLSchema\"{(attributes.Length == 0 ? string.Empty : " " + attributes)}>{body}</xs:schema>";

    private static string Create(string attributes, string body) =>
        $"create xml schema collection x as N'{Text(attributes, body).Replace("'", "''", StringComparison.Ordinal)}'";

    private static void AssertRefused(string attributes, string body, int number, int state, string message)
    {
        var ex = new Simulation().AssertSqlError(Create(attributes, body), number);
        AreEqual(message, ex.Errors[0].Message);
        AreEqual(state, ex.State);
    }

    /// <summary>The first two passes: the top level of each document, then each declaration's subtree in document order.</summary>
    [TestMethod]
    [DataRow("", """<xs:element name="a" foo="1"/><xs:element name="b" type="nosuch"/>""", 2298, 1, "Attribute 'foo' is not valid at location '/*:schema[1]/*:element[1]'.")]
    [DataRow("", """<xs:foo/><xs:element name="b" type="nosuch"/>""", 2297, 1, "Element <foo> is not valid at location '/*:schema[1]/*:foo[1]'.")]
    [DataRow("", """<xs:simpleType name="s"><xs:restriction base="xs:string"><xs:minInclusive value="1"/></xs:restriction></xs:simpleType><xs:element name="b" type="nosuch"/>""", 2319, 1, "This type may not have a 'minInclusive' facet. Location: '/*:schema[1]/*:simpleType[1]/*:restriction[1]/*:minInclusive[1]'.")]
    [DataRow("", """<xs:simpleType name="s"><xs:restriction base="xs:string"><xs:maxLength value="x"/></xs:restriction></xs:simpleType><xs:element name="b" type="nosuch"/>""", 2309, 1, "The value of \"value\" is not a valid number.")]
    [DataRow("", """<xs:element name="r" type="xs:string"><xs:complexType/></xs:element><xs:element name="b" type="nosuch"/>""", 2305, 1, "Element or attribute type specified more than once. Location: '/*:schema[1]/*:element[1]/*:complexType[1]'.")]
    [DataRow("", """<xs:element name="r"><xs:complexType><xs:attribute name="a"/><xs:attribute name="a"/></xs:complexType></xs:element><xs:element name="b" type="nosuch"/>""", 2310, 1, "The attribute \"a\" is declared more than once.")]
    [DataRow("", """<xs:element name="r"><xs:complexType><xs:sequence><xs:element name="a" minOccurs="3" maxOccurs="2"/></xs:sequence></xs:complexType></xs:element><xs:element name="b" type="nosuch"/>""", 2382, 1, "Invalid combination of minOccurs and maxOccurs values, minOccurs has to be less than or equal to maxOccurs. Location: '/*:schema[1]/*:element[1]/*:complexType[1]/*:sequence[1]/*:element[1]'.")]
    [DataRow("", """<xs:element type="xs:string"/><xs:element name="b" type="nosuch"/>""", 2299, 1, "Required attribute \"name\" of XSD element \"element\" is missing.")]
    [DataRow("", """<xs:complexType name="c"><xs:choice/></xs:complexType><xs:element name="b" type="nosuch"/>""", 2293, 1, "Choice cannot be empty unless minOccurs is 0. Location: '/*:schema[1]/*:complexType[1]/*:choice[1]'.")]
    [DataRow("", """<xs:element name="b" foo="1"/><xs:element name="r" type="1"/>""", 2298, 1, "Attribute 'foo' is not valid at location '/*:schema[1]/*:element[1]'.")]
    [DataRow("", """<xs:element name="r"><xs:sequence/></xs:element><xs:element name="z"><xs:unique name="u"><xs:selector xpath="."/><xs:field xpath="."/></xs:unique></xs:element>""", 2297, 1, "Element <sequence> is not valid at location '/*:schema[1]/*:element[1]/*:sequence[1]'.")]
    [DataRow("", """<xs:element name="r"><xs:sequence/></xs:element><xs:element name="b" type="xs:int"/><xs:element name="b"/>""", 2297, 1, "Element <sequence> is not valid at location '/*:schema[1]/*:element[1]/*:sequence[1]'.")]
    [DataRow("", """<xs:foo/><xs:element name="b"/><xs:element name="b"/>""", 2297, 1, "Element <foo> is not valid at location '/*:schema[1]/*:foo[1]'.")]
    [DataRow("", """<xs:element name="b"/><xs:element name="r"><xs:sequence/></xs:element><xs:element name="b"/>""", 2302, 1, "The name \"b\" has already been defined in this scope.")]
    [DataRow("", """<xs:element name="r" foo="1"/><xs:element name="b"/><xs:element name="b"/>""", 2298, 1, "Attribute 'foo' is not valid at location '/*:schema[1]/*:element[1]'.")]
    [DataRow("", """<xs:element name="r" foo="1"/><xs:element name="z"/><xs:element name="r"/>""", 2302, 1, "The name \"r\" has already been defined in this scope.")]
