    [TestMethod]
    public void AnAlter_IsJudgedBeforeItsRedeclarations()
    {
        var simulation = new Simulation();
        _ = simulation.ExecuteNonQuery("""create xml schema collection x as N'<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema"><xs:element name="a" type="xs:int"/><xs:simpleType name="b"><xs:restriction base="xs:string"><xs:maxLength value="5"/></xs:restriction></xs:simpleType></xs:schema>'""");
        simulation.AssertSqlError(
            """alter xml schema collection x add N'<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema"><xs:element name="a" type="xs:int"/><xs:element name="e" type="xs:int" default="x"/></xs:schema>'""",
            6926,
            "XML Validation: Invalid simple type value: 'x'. Location: xs-nun(/e)");
        simulation.AssertSqlError(
            """alter xml schema collection x add N'<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema"><xs:element name="z"><xs:sequence/></xs:element><xs:element name="a" type="xs:int"/></xs:schema>'""",
            2297,
            "Element <sequence> is not valid at location '/*:schema[1]/*:element[1]/*:sequence[1]'.");
        simulation.AssertSqlError(
            """alter xml schema collection x add N'<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema"><xs:simpleType name="b"><xs:restriction base="xs:int"/></xs:simpleType><xs:simpleType name="b"><xs:restriction base="xs:int"/></xs:simpleType></xs:schema>'""",
            2302,
            "The name \"b\" has already been defined in this scope.");
        _ = simulation.AssertSqlError(
            """alter xml schema collection x add N'<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema"><xs:element name="z"/><xs:element name="a" type="xs:int"/></xs:schema>'""",
            6310);
    }

    [TestMethod]
    public void AnAlter_ResolvesAgainstTheCollection()
    {
        var simulation = new Simulation();
        _ = simulation.ExecuteNonQuery("""create xml schema collection x as N'<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema"><xs:simpleType name="b"><xs:restriction base="xs:string"><xs:maxLength value="5"/></xs:restriction></xs:simpleType></xs:schema>'""");
        simulation.AssertSqlError(
            """alter xml schema collection x add N'<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema"><xs:simpleType name="d"><xs:restriction base="b"><xs:maxLength value="10"/></xs:restriction></xs:simpleType></xs:schema>'""",
            6944,
            "Invalid type definition for type 'd', 'maxLength' facet is not restricting the value space");
        simulation.AssertSqlError(
            """alter xml schema collection x add N'<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema"><xs:element name="e" type="b" default="toolong"/></xs:schema>'""",
            6926,
            "XML Validation: Invalid simple type value: 'toolong'. Location: xs-nun(/e)");
        _ = simulation.ExecuteNonQuery("""alter xml schema collection x add N'<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema"><xs:element name="e" type="b" default="short"/></xs:schema>'""");
    }

    [TestMethod]
    public void ARefusedAlter_SpendsNoComponentIds()
    {
        var simulation = new Simulation();
        _ = simulation.ExecuteNonQuery("""create xml schema collection x as N'<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema"><xs:element name="a" type="xs:int"/></xs:schema>'""");
        _ = simulation.AssertSqlError("""alter xml schema collection x add N'<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema" targetNamespace="urn:q"><xs:element name="b" type="xs:int"/><xs:element name="c" type="xs:int" default="x"/></xs:schema>'""", 6926);
        _ = simulation.AssertSqlError("""alter xml schema collection x add N'<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema" targetNamespace="urn:q"><xs:element name="b" type="xs:int"/><xs:element name="c"><xs:complexType><xs:sequence><xs:any minOccurs="0"/><xs:any/></xs:sequence></xs:complexType></xs:element></xs:schema>'""", 6916);
        _ = simulation.ExecuteNonQuery("""alter xml schema collection x add N'<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema" targetNamespace="urn:r"><xs:element name="d" type="xs:int"/></xs:schema>'""");
        AreEqual(1, simulation.ExecuteScalar("select max(xml_component_id) - min(xml_component_id) from sys.xml_schema_components where xml_collection_id = (select xml_collection_id from sys.xml_schema_collections where name = 'x')"));
    }

    [TestMethod]
    public void TheCompileRefusals_ActAsUnderXactAbort()
    {
        var simulation = new Simulation();
        using var connection = simulation.CreateOpenConnection();
        _ = Throws<SimulatedSqlException>(() => connection.CreateCommand(
            $"begin tran; {Create(string.Empty, "<xs:element name=\"r\"><xs:complexType><xs:sequence><xs:any minOccurs=\"0\"/><xs:any/></xs:sequence></xs:complexType></xs:element>")}; select 1").ExecuteNonQuery());
        AreEqual(0, connection.CreateCommand("select @@trancount").ExecuteScalar());
    }
